@JvmName("step80")
fun step80(limit: Int): Int {
    var total = 0
    for (index in 1..limit) {
        total += index
    }
    return total + 12
}
sealed class Outcome81 {
    data class Success(val payload: String) : Outcome81()
    data object Failure : Outcome81()
}

fun describe81(outcome: Outcome81): String = when (outcome) {
    is Outcome81.Success -> outcome.payload
    Outcome81.Failure -> "failed"
}
